B.ao4=new A.iQ("kennelLogo","Logo","Upload a logo image for your kennel.\n\nThis image is displayed on the Harrier Central map and in run listings. A square image with a transparent background works best.",B.k_,!0,!1,!0,!1,4,"kennelLogo")
